import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.AuRYXM_l.js";const m=JSON.parse('{"title":"Chainy project documentation","description":"The public documentation library renders all project Markdown with search, categories and historical notices. The source repository remains private. See viewer operations for ","frontmatter":{"title":"Chainy project documentation","description":"The public documentation library renders all project Markdown with search, categories and historical notices. The source repository remains private. See viewer operations for ","source":"docs/documentation-index.md","category":"Start here","sourceUpdated":null,"outline":[2,3]},"headers":[],"relativePath":"content/docs/documentation-index.md","filePath":"content/docs/documentation-index.md"}'),r={name:"content/docs/documentation-index.md"};function o(d,e,s,c,l,h){return a(),n("div",null,[...e[0]||(e[0]=[i('<div><h1 id="chainy-project-documentation">Chainy project documentation<a class="header-anchor" href="#chainy-project-documentation" aria-label="Link to this section">​</a></h1><p>The <a href="https://owenlim225.github.io/Chainy-Docs/">public documentation library</a> renders all project Markdown with search, categories and historical notices. The source repository remains private. See <a href="/Chainy-Docs/content/tools/docs-viewer/readme.html">viewer operations</a> for publishing and maintenance.</p><p>This is the project&#39;s design and delivery reference, prepared October 5, 2026 before game implementation. Start with the confirmed baseline, then use the relevant specification and your assigned work packet. Detailed design choices marked proposed are reviewable recommendations; their presence in a document does not make them tested or school-approved.</p><h2 id="october-8-coordinated-game-development-package">October 8 coordinated game-development package<a class="header-anchor" href="#october-8-coordinated-game-development-package" aria-label="Link to this section">​</a></h2><p>The requested package is reconciled with existing specifications. Current scope remains in the baseline; detailed design choices remain proposals until accepted/validated. Read the PRD and GDD together, then dispatch bounded tasks using the implementation plan.</p><table><thead><tr><th>Requested deliverable</th><th>Canonical document</th><th>Boundary</th></tr></thead><tbody><tr><td>1. Product requirement document</td><td><a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">PRD</a></td><td>Users, goals, CH-R01–12 acceptance and scope</td></tr><tr><td>2. Technical requirement document</td><td><a href="/Chainy-Docs/content/docs/requirements/technical-requirements.html">Technical requirements</a></td><td>Verifiable technical contracts; complements existing architecture</td></tr><tr><td>3. App flow document</td><td><a href="/Chainy-Docs/content/docs/design/app-flow.html">Game/app flow</a></td><td>States, guards, transitions and failure recovery</td></tr><tr><td>4. Design brief document</td><td><a href="/Chainy-Docs/content/docs/design/design-brief.html">Design brief</a></td><td>Teen visual/interaction direction, assets and production handoffs</td></tr><tr><td>5. Background schema, clarified as SQLite database schema</td><td><a href="/Chainy-Docs/content/docs/design/database-schema.html">Database schema</a> and <a href="/Chainy-Docs/attachments/docs/design/local-schema.sql">SQL</a></td><td>Fields, relationships, integrity, lifecycle and export boundaries</td></tr><tr><td>6. Implementation plan</td><td><a href="/Chainy-Docs/content/docs/planning/implementation-plan.html">Parallel implementation</a> and <a href="/Chainy-Docs/content/docs/planning/agent-task-packets.html">agent task packets</a></td><td>Dependency gates, exclusive write ownership, integration and acceptance</td></tr><tr><td>Game design document</td><td><a href="/Chainy-Docs/content/docs/game-design.html">GDD</a></td><td>Core loop, three levels, construction, learning and progression</td></tr></tbody></table><p>Repository organization: requirements/ contains product and technical acceptance; design/ contains flow, brief and data design; planning/ contains dispatch guidance and the move record; archive/ contains historical evidence. Existing active baseline, schedule, team, manuscript and QA paths remain stable. Tooling stays under tools/. <a href="/Chainy-Docs/content/docs/archive/readme.html">Archive guide</a> explains historical precedence; <a href="/Chainy-Docs/attachments/docs/planning/repository-move-manifest.json">move manifest</a> preserves old paths and verifies unchanged source contents.</p><p>The latest October 8 request prioritizes the <a href="/Chainy-Docs/content/docs/game-design.html">complete illustrated GDD</a> in the supplied template. Images 1–2 define the visual style; Image 3 adds gameplay context only. The <a href="/Chainy-Docs/content/docs/media/gdd/readme.html">media register</a> distinguishes supplied references, generated illustrations and the numbered flow diagram. Individual availability is unknown; see the <a href="/Chainy-Docs/content/docs/team-delegation.html#october-8-workload-balancing-proposal">balanced planning estimates</a>. Tambunan National High School, Marinduque is the tentative November 3–6 beta opportunity; the <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">revised conditional forecast</a> moves readiness earlier. See the <a href="/Chainy-Docs/content/docs/planning/documentation-verification.html">documentation verification record</a> for completed checks and their limits. No issue status, due date or external assignment was changed by this documentation update. <strong>November 21, 2026</strong> remains the pre-final deadline.</p><h2 id="read-in-this-order">Read in this order<a class="header-anchor" href="#read-in-this-order" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Document</th><th>Purpose</th><th>Accountable lead</th></tr></thead><tbody><tr><td><a href="/Chainy-Docs/content/docs/project-baseline.html">Current baseline</a></td><td>Confirmed scope, requirement IDs, decisions and unresolved questions</td><td>Sherwin</td></tr><tr><td><a href="/Chainy-Docs/content/docs/game-design.html">Game design</a></td><td>Learning objectives, level rules, player loop, UI, content and asset contracts</td><td>Sherwin; Luis/Miguel contribute</td></tr><tr><td><a href="/Chainy-Docs/content/docs/technical-design.html">Technical design</a></td><td>Components, state transitions, identity, persistence, export and recovery</td><td>Christian</td></tr><tr><td><a href="/Chainy-Docs/attachments/docs/design/local-schema.sql">SQLite design schema</a></td><td>Proposed relational schema to validate with the chosen Android binding</td><td>Christian</td></tr><tr><td><a href="/Chainy-Docs/content/docs/hardware-validation.html">Hardware validation</a></td><td>Proposed device class, measurable budgets and device-spike evidence</td><td>Christian</td></tr><tr><td><a href="/Chainy-Docs/content/docs/offline-data-plan.html">Offline evidence plan</a></td><td>Teacher operation, transfer and learner-code boundaries</td><td>Sean and Christian</td></tr><tr><td><a href="/Chainy-Docs/content/docs/qa-evaluation.html">QA and evaluation</a></td><td>Test matrix, pilot procedure, draft assessment blueprint and analysis limits</td><td>Sean; technical checks by team</td></tr><tr><td><a href="/Chainy-Docs/content/docs/user-guide.html">Learner and teacher guide</a></td><td>Proposed operating instructions and recovery guidance</td><td>Miguel; Sean review</td></tr><tr><td><a href="/Chainy-Docs/content/docs/team-delegation.html">Team delegation</a></td><td>Individual task packets, support, review and handoff responsibilities</td><td>Sherwin</td></tr><tr><td><a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">Recovery schedule</a></td><td>Dependencies, checkpoints and November 21 deadline</td><td>Sherwin</td></tr><tr><td><a href="/Chainy-Docs/content/docs/manuscript-working-draft.html">Manuscript working draft</a></td><td>Substantive introduction/methodology draft, literature work and evidence boundaries</td><td>Sean</td></tr><tr><td><a href="/Chainy-Docs/content/docs/manuscript-evidence-map.html">Official manuscript evidence map</a></td><td>Required sections and appendices A–M, owners and actual evidence</td><td>Sean</td></tr><tr><td><a href="/Chainy-Docs/content/docs/mentors.html">Mentors</a></td><td>When to challenge scope, feasibility, accuracy and evidence</td><td>Relevant reviewer</td></tr></tbody></table><p><a href="https://github.com/orgs/Kamiyon-Studio/projects/5">Live board</a> is the execution view. <a href="/Chainy-Docs/attachments/docs/backlog.json">Backlog inventory</a> records issue links and named task assignments. GitHub accounts are not required: teammates can update linked tasks in the <a href="https://trello.com/b/VPH0LHFN/capstone-t13">Trello board</a>. The <a href="/Chainy-Docs/content/tools/kanban-sync/readme.html">integration guide</a> explains synchronized fields and limits; Sherwin handles unlinked tasks and sync exceptions. Creating a name field does not notify a person or create an account.</p><h2 id="documentation-first-with-a-finite-review">Documentation first with a finite review<a class="header-anchor" href="#documentation-first-with-a-finite-review" aria-label="Link to this section">​</a></h2><p>Review this specification now; record accepted changes and unresolved blockers on CH-02. A proposed two-day design-review window protects the October 9–11 device spike. Full documentation first means the team shares an actionable design before production; it does not require writing unobserved results before a prototype exists. A request for a major mechanic change reopens affected contracts rather than forcing a rewrite of every document.</p><p>A document is ready for implementation when its rules/interfaces, owner and acceptance checks are clear, and remaining unknowns are bounded tests. School submission readiness additionally requires verified literature, required approvals, actual build results and pilot evidence. This package does not claim those are complete.</p><h2 id="current-decision-register">Current decision register<a class="header-anchor" href="#current-decision-register" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Decision</th><th>Status</th></tr></thead><tbody><tr><td>English first</td><td>Confirmed by user</td></tr><tr><td>Name-based team assignment</td><td>Confirmed; no fake GitHub accounts</td></tr><tr><td>SQLite persistence</td><td>Confirmed</td></tr><tr><td>Teacher-issued learner code</td><td>Adopted for offline profile identification; not verified login authentication</td></tr><tr><td>Android 11+ provisional baseline, Android 10 candidate</td><td>Mentor recommendation resolving the user&#39;s 10+/11+ alternative; requires device validation</td></tr><tr><td>4 GB physical RAM and ARM64</td><td>User-proposed target class; performance unverified</td></tr><tr><td>64 GB total capacity</td><td>Device class only; proposed free-space budget is separate</td></tr><tr><td>ES 3.2 or Vulkan 1.1</td><td>User proposal; simplest supported render path to be chosen from actual tests</td></tr><tr><td>Exact ISO instrument/version</td><td>Still pending; user will provide details</td></tr><tr><td>Beta site/window</td><td>Tambunan National High School, Marinduque; November 3–6 possible, not confirmed booking</td></tr><tr><td>Named pilot contact, formal booking, instruments and actual device inventory</td><td>Not yet received; required for actual sessions</td></tr><tr><td>Visual direction</td><td>Chainy Images 1–2 confirmed; BlockForge Image 3 is gameplay context only</td></tr><tr><td>Team hours</td><td>Actual availability unknown; user authorizes balanced planning estimates</td></tr><tr><td>Complete manuscript chapters and pilot evidence by November 21</td><td>Mandatory; results cannot be fabricated</td></tr></tbody></table><p>No participant exports, identity mapping, passwords or signing keys belong in either repository. Keep source documents unchanged as historical material; the latest user decisions and current baseline govern development.</p></div>',1)])])}const u=t(r,[["render",o]]);export{m as __pageData,u as default};
